// function add(a, b) mein do values do
// Agar dono numbers nahi: "Both must be numbers"
// Agar sirf a number nahi: "First must be a number"
// Agar sirf b number nahi: "Second must be a number"
// Warna sum return karo

solution:
function add(a, b) {
  if (typeof a !== "number" && typeof b !== "number") return "Both must be numbers"
  if (typeof a !== "number") return "First must be a number"
  if (typeof b !== "number") return "Second must be a number"
  return a + b
}
